        org.junit.Assert.assertEquals(document1, document2);
    }

    @Test
    public void connectionEquals_ConnectionReturnsSameConnection() {
        Connection connection1 = new Connection();
        Connection connection2 = new Connection();
        connection2.setUri("https://www.example.com");
        Document document = new Document("https://www.example.com").connection(connection1);
        org.junit.Assert.assertEquals(document.connection(), connection2);
    }

    @Test
    public void text_SingleCharacterReturnsCorrectHtml() {
        String text = "a";
        Element element = new Document("https://www.example.com").text(text);
        org.junit.Assert.assertEquals("<a>", element.outerHtml());
    }

    @Test
    public void text_MultipleCharactersReturnsCorrectHtml() {
        String text = "abc";
        Element element = new Document("https://www.example.com").text(text);
        org.junit.Assert.assertEquals("<abc>", element.outerHtml());
    }
